#include <iostream>
#include <memory>
#include <vector>

class Gadget {
public:
    ~Gadget() { std::cout << "Gadget destroyed.\n"; }
};

void process_gadgets(std::shared_ptr<Gadget> sp) {
    std::cout << "Inside function, use_count: " << sp.use_count() << std::endl;
    // sp goes out of scope here, ref count is decremented.
}

int main() {
    std::shared_ptr<Gadget> sp1(new Gadget());
    std::cout << "After creation, use_count: " << sp1.use_count() << std::endl; // count is 1

    {
        std::shared_ptr<Gadget> sp2 = sp1; // Copy construction
        std::cout << "After copy, use_count: " << sp1.use_count() << std::endl; // count is 2
        process_gadgets(sp2); // Pass by value (another copy)
        std::cout << "After function call, use_count: " << sp1.use_count() << std::endl; // count is 2
    } // sp2 goes out of scope here

    std::cout << "After inner scope, use_count: " << sp1.use_count() << std::endl; // count is 1

    sp1.reset(); // Manually release ownership
    std::cout << "After reset, use_count: " << sp1.use_count() << std::endl; // count is 0, Gadget destroyed

    return 0;
}
